          opt(["Pay to make it go away", "Betala för att få bort det"], "x3", ["Nothing guarantees the files are deleted, and you have shown you pay.", "Inget garanterar att filerna raderas, och ni har visat att ni betalar."], { pushback: [
            pb(["How will you know?", "Hur vet ni det?"], ["The sender offers no proof the files will be deleted and no way to check. If a new demand arrives next month, what did you buy?", "Avsändaren ger inga bevis för att filerna raderas och inget sätt att kontrollera det. Om ett nytt krav kommer nästa månad, vad har ni då köpt?"]),
            pb(["Who authorises it?", "Vem godkänner det?"], ["Legal says a payment like this may need board approval and could break the law depending on who receives it. The CFO wants to sign it. Who actually authorises paying an extortionist?", "Juristen säger att en sådan betalning kan kräva styrelsens godkännande och kan vara olaglig beroende på vem som tar emot den. Ekonomichefen vill skriva under. Vem godkänner egentligen en betalning till en utpressare?"]),
            pb(["The insurer says no", "Försäkringsbolaget säger nej"], ["The insurance terms say any payment without the insurer's approval may void cover for the whole incident. The insurer will not approve it. Do you pay anyway?", "Försäkringsvillkoren säger att en betalning utan försäkringsbolagets godkännande kan ogiltigförklara skyddet för hela incidenten. Försäkringsbolaget godkänner den inte. Betalar ni ändå?"])
          ] }),
          opt(["Negotiate for time", "Förhandla för att vinna tid"], "x3", ["Time for what? Decide that before you start talking.", "Tid för vad? Bestäm det innan ni börjar prata."], { pushback: [
            pb(["A sign of good faith", "Ett tecken på god vilja"], ["The sender agrees to wait one more day, but wants a part payment “as a sign of good faith”. Is that already paying, and where does it end?", "Avsändaren går med på att vänta en dag till, men vill ha en delbetalning ”som ett tecken på god vilja”. Är det redan att betala, och var slutar det?"]),
            pb(["Nobody here has done this", "Ingen här har gjort det"], ["Nobody in the room has negotiated with a criminal, and anything written to them can read as a promise. Do you bring in the police or a specialist before replying, and how fast?", "Ingen i rummet har förhandlat med en brottsling, och allt som skrivs till dem kan läsas som ett löfte. Tar ni in polisen eller en specialist innan ni svarar, och hur snabbt?"]),
            pb(["Time may already be gone", "Tiden kanske redan är slut"], ["While you talk, you cannot know whether the files have already been passed to others. The time you buy may be time you do not have. What exactly will you do with it?", "Medan ni pratar kan ni inte veta om filerna redan har gått vidare till andra. Tiden ni köper kanske inte finns. Vad exakt ska ni göra med den?"])
          ] })
